import {receivingProgress} from './faculty.js?v=1.2.2';
export function homeMarkup({records,catalog,observatory,esc,region}) {
  const faculty=catalog.faculty.people, schools=receivingProgress(catalog);
  const complete=observatory.audit.filter(c=>c.cohort_complete).length;
  const current=records.filter(r=>r.market_cycle===catalog.current_cycle).length;
  const fmt=n=>n.toLocaleString('en-US');
  const tasks=[
    ['01','PhD placements','Where did recent graduates go?','Search people, research fields and first or final job-market arrangements.','#directory','Browse placements'],
    ['02','Faculty directory','Who works in a department now?','Trace faculty members back to their PhD programs and dated career evidence.','#faculty','Explore faculty'],
    ['03','Open positions','Who is hiring, and in which fields?','Browse sourced advertisements, deadlines and appointment types.','#jobs','View positions']
  ];
  const destinations=new Map();
  for(const r of records)if(r.destination_region&&r.destination)destinations.set(r.destination_region,(destinations.get(r.destination_region)||0)+1);
  const top=[...destinations].sort((a,b)=>b[1]-a[1]).slice(0,5), max=Math.max(1,...top.map(x=>x[1]));
  return `<section class="home-hero"><div><p class="eyebrow">AN EVIDENCE-LED ACADEMIC MARKET OBSERVATORY</p><h1>Follow the people.<br><span>Understand the market.</span></h1><p class="hero-description">Explore Marketing and Economics IO through PhD placements, faculty careers and hiring demand. Every record leads back to its sources.</p><div class="hero-actions"><a class="button" href="#directory">Explore placements <span aria-hidden="true">→</span></a><a class="hero-link" href="#method">How to read this data ↗</a></div></div><aside class="hero-note"><span class="small-label">THE CURRENT DATA EDITION</span><strong>${esc(catalog.updated_at)}</strong><p>Training programs in the US, Canada, Hong Kong and Singapore. Destinations worldwide.</p><a href="#coverage">See the exact coverage →</a></aside></section>
  <section class="home-metrics" aria-label="Separate data collections"><a href="#directory?period=all"><strong>${fmt(records.length)}</strong><span>placement records</span><small>${fmt(records.filter(r=>r.placement_year).length)} with a first-job year</small></a><a href="#faculty"><strong>${fmt(faculty.length)}</strong><span>faculty profiles</span><small>${fmt(schools.length)} receiving institutions in scope</small></a><a href="#jobs"><strong>${fmt(observatory.jobs.length)}</strong><span>sourced job advertisements</span><small>Current and historical advertisements</small></a><a href="#coverage"><strong>${fmt(complete)}</strong><span>confirmed complete cohorts</span><small>Roster and outcome completeness differ</small></a></section>
  <div class="section-intro"><div><p class="eyebrow">START WITH YOUR QUESTION</p><h2>Three collections. Three ways in.</h2></div><p>Placement records and faculty profiles describe different populations. Their totals are kept separate.</p></div>
  <section class="task-grid" aria-label="Explore the collections">${tasks.map(([n,title,q,desc,url,link])=>`<a class="task-card" href="${url}"><div class="task-card-top"><span>${n}</span><span aria-hidden="true">↗</span></div><p class="small-label">${title}</p><h3>${q}</h3><p>${desc}</p><strong>${link} <span aria-hidden="true">→</span></strong></a>`).join('')}</section>
  <section class="home-analysis"><div class="home-analysis-intro"><p class="eyebrow">LOOK ACROSS RECORDS</p><h2>Find a pattern.<br>Then inspect the evidence.</h2><p>Use consistent years and definitions before comparing programs or following a flow.</p><div class="analysis-links"><a href="#compare">Compare 2–5 programs <span>→</span></a><a href="#flows">Explore destination flows <span>→</span></a><a href="#current">Track ${esc(catalog.current_cycle)} candidates <span>${fmt(current)} records →</span></a></div></div><div class="destination-preview"><div class="preview-heading"><h3>First-job destinations</h3><span>All collected records</span></div>${top.map(([r,n])=>`<a class="preview-bar" href="#directory?period=all&basis=first&destination=${encodeURIComponent(r)}"><span>${esc(region(r))}</span><strong>${n}</strong><i style="--bar-width:${n/max*100}%"></i></a>`).join('')}<p class="muted">Counts require a recorded employer; unverified regions are shown separately. Unknown employers remain in the directory. Collection coverage varies by program and year.</p></div></section>
  <section class="trust-strip"><div><span class="trust-symbol" aria-hidden="true">◎</span><h2>Know what the evidence can support.</h2><p>This is an expanding public-source sample. A matched source list is not proof of a complete graduating cohort, and a faculty title alone does not confirm tenure status.</p></div><div class="trust-links"><a href="#quality">Data quality & missing fields →</a><a href="#faculty?faculty_view=progress">School-by-school faculty coverage →</a><a href="#method">Definitions & statistical boundaries →</a></div></section><p class="footer-note">English interface · Original source quotations and verification notes retain their source language · Data observed through ${esc(observatory.as_of)}.</p>`;
}
